_SUPPORTED = ("en", "fr", "ru", "ja", "es", "zh", "ar", "de", "pt", "ko", "tr", "hi", "nl", "it", "tl", "hu", "sw", "id", "vi", "th", "pl", "uk", "fa", "ur", "ms", "ro", "el")
_expected_keys = set(C5_CLOSURE_TRANSLATIONS["en"])
if set(C5_CLOSURE_TRANSLATIONS) != set(_SUPPORTED):
    raise RuntimeError("C5 closure translations do not cover every supported language")
for _language, _values in C5_CLOSURE_TRANSLATIONS.items():
    if set(_values) != _expected_keys:
        raise RuntimeError(f"C5 closure translation key mismatch: {_language}")
